[TestMethod]
	public async ValueTask Resolve()
	{
		await using var container = Container.Create(services =>
													 {
														 services.AddType<TransientService>();
														 services.AddSharedType<ScopedService>(SharedWithin.Scope);
														 services.AddSharedType<SingletonService>(SharedWithin.Container);
													 });

		// Root container resolutions
		var transientA = await container.GetRequiredService<TransientService>();
		var transientB = await container.GetRequiredService<TransientService>();
		var scopedRootA = await container.GetRequiredService<ScopedService>();
		var scopedRootB = await container.GetRequiredService<ScopedService>();
		var singletonRootA = await container.GetRequiredService<SingletonService>();
		var singletonRootB = await container.GetRequiredService<SingletonService>();

		// Create child scope
		var scopeFactory = await container.GetRequiredService<IServiceScopeFactory>();
		await using var scope = scopeFactory.CreateScope();
		var scopedProvider = scope.ServiceProvider;

		var transientScopeA = await scopedProvider.GetRequiredService<TransientService>();
		var transientScopeB = await scopedProvider.GetRequiredService<TransientService>();
		var scopedChildA = await scopedProvider.GetRequiredService<ScopedService>();
		var scopedChildB = await scopedProvider.GetRequiredService<ScopedService>();
		var singletonChildA = await scopedProvider.GetRequiredService<SingletonService>();
		var singletonChildB = await scopedProvider.GetRequiredService<SingletonService>();

		// Transient: always different
		Assert.AreNotSame(transientA, transientB);
		Assert.AreNotSame(transientScopeA, transientScopeB);
		Assert.AreNotSame(transientA, transientScopeA);

		// Scoped: same within same provider, different across root and child scope
		Assert.AreSame(scopedRootA, scopedRootB);
		Assert.AreSame(scopedChildA, scopedChildB);
		Assert.AreNotSame(scopedRootA, scopedChildA);

		// Singleton (container): same across all resolutions and scopes
		Assert.AreSame(singletonRootA, singletonRootB);
		Assert.AreSame(singletonChildA, singletonChildB);
		Assert.AreSame(singletonRootA, singletonChildA);
	}

[TestMethod]
	public async ValueTask Enumerate()
	{
		await using var container = Container.Create(services =>
													 {
														 // Register two implementations for the same interface
														 services.AddImplementation<AlphaProcessor>().For<IProcessor>();
														 services.AddImplementation<BetaProcessor>().For<IProcessor>();

														 // Register three argument-based services (same concrete type, same argument type)
														 services.AddType<ValueTaggedService, int>();
														 services.AddType<ValueTaggedService, int>();
														 services.AddType<ValueTaggedService, int>();
													 });

		// Enumerate all IProcessor instances
		var processorIds = new List<string>();

		await foreach (var p in container.GetServices<IProcessor>())
		{
			processorIds.Add(p.Id);
		}

		Assert.HasCount(expected: 2, processorIds);
		CollectionAssert.AreEquivalent(new List<string> { "Alpha", "Beta" }, processorIds);

		// Enumerate all ValueTaggedService instances for argument 42
		var valueInstances = new List<int>();

		await foreach (var svc in container.GetServices<ValueTaggedService, int>(42))
		{
			valueInstances.Add(svc.Value);
		}

		Assert.HasCount(expected: 3, valueInstances);
		Assert.IsTrue(valueInstances.TrueForAll(v => v == 42));
	}

[TestMethod]
	public async ValueTask Resolve()
	{
		await using var container = Container.Create(services =>
													 {
														 services.AddTypeSync<SyncService>();  // synchronous construction
														 services.AddType<AsyncInitService>(); // asynchronous initialization
													 });

		// Synchronous resolution of SyncService
		var syncInst1 = container.GetRequiredServiceSync<SyncService>();
		Assert.IsNotNull(syncInst1);

		// Asynchronous resolution of synchronous SyncService is acceptable too
		var syncInst2 = await container.GetRequiredService<SyncService>();
		Assert.IsNotNull(syncInst2);

		// Asynchronous resolution of AsyncInitService (awaits initialization internally)
		var asyncInst = await container.GetRequiredService<AsyncInitService>();
		Assert.AreEqual(expected: "Initialized", asyncInst.Data);

		// Synchronous resolution attempt for async initialized service should throw
		Assert.ThrowsExactly<DependencyInjectionException>(container.GetRequiredServiceSync<AsyncInitService>);
	}

[TestMethod]
	public async Task AncestorSimpleTest_ShouldResolveDependenciesCorrectly()
	{
		// Arrange
		await using var container = Container.Create(s =>
													 {
														 s.AddType<ChildPost>();
														 s.AddType<GrandParent>();
														 s.AddType<Parent>();
														 s.AddType<Child>();
														 s.AddType<Child, int>();
														 s.AddImplementation<LazyImpl<Any>>().For<ILazy<Any>>();
														 s.AddSharedImplementationSync<ServiceProviderActions>(SharedWithin.Scope).For<ServiceProviderActions>().For<IServiceProviderActions>();
														 s.AddFactory<LazyImpl<Any>>().For<Lazy<Any>>();
													 });

		// Act
		var grandParent = await container.GetRequiredService<GrandParent>();
		var childPost = await container.GetRequiredService<ChildPost>();
		var child = await container.GetRequiredService<Child, int>(5);

		// Assert
		Assert.AreEqual(typeof(Parent), grandParent.ParentInstance.ChildInstance.ParentInstance1.Value!.GetType());
		Assert.AreEqual(typeof(Parent), grandParent.ParentInstance.ChildInstance.ParentInstance2.Value!.GetType());
		Assert.AreEqual(typeof(Parent), grandParent.ParentInstance.ChildInstance.ParentInstance3.Value!.GetType());
		Assert.AreEqual(typeof(GrandParent), grandParent.ParentInstance.GrandParentInstance.Value!.GetType());
		Assert.AreEqual(typeof(Parent), childPost.ParentInstance.Value!.GetType());
		Assert.AreEqual(typeof(Parent), childPost.ParentInstanceGetter().GetType());
		Assert.IsNotNull(child);
	}

